PRAGMA defer_foreign_keys=TRUE;
CREATE TABLE app_meta (
    key TEXT PRIMARY KEY,
    value TEXT NOT NULL
  );
CREATE TABLE company (
    id TEXT PRIMARY KEY,
    name TEXT NOT NULL,
    legal_name TEXT,
    email TEXT,
    phone TEXT,
    address1 TEXT,
    address2 TEXT,
    city TEXT,
    postal_code TEXT,
    country TEXT NOT NULL DEFAULT 'Polynésie française',
    timezone TEXT NOT NULL DEFAULT 'Pacific/Tahiti',
    currency TEXT NOT NULL DEFAULT 'XPF',
    locale TEXT NOT NULL DEFAULT 'fr-FR',
    tax_id TEXT,
    rcs TEXT,
    share_capital TEXT,
    vat_regime TEXT NOT NULL DEFAULT 'standard',
    logo_url TEXT,
    default_tax_rate INTEGER NOT NULL DEFAULT 16,
    payment_terms INTEGER NOT NULL DEFAULT 30,
    number_pattern TEXT NOT NULL DEFAULT '{prefix}-{YYYY}-{####}',
    invoice_terms TEXT,
    invoice_footer TEXT,
    legal_notes TEXT,
    bank_name TEXT,
    bank_holder TEXT,
    bank_iban TEXT,
    bank_bic TEXT,
    session_idle_minutes INTEGER NOT NULL DEFAULT 30,
    session_absolute_hours INTEGER NOT NULL DEFAULT 12,
    created_at TEXT NOT NULL,
    updated_at TEXT NOT NULL
  );
CREATE TABLE users (
    id TEXT PRIMARY KEY,
    email TEXT NOT NULL UNIQUE,
    password_hash TEXT NOT NULL,
    first_name TEXT NOT NULL,
    last_name TEXT NOT NULL,
    role TEXT NOT NULL DEFAULT 'viewer',
    is_active INTEGER NOT NULL DEFAULT 1,
    last_login_at TEXT,
    created_at TEXT NOT NULL,
    updated_at TEXT NOT NULL,
    deleted_at TEXT
  , mfa_secret TEXT, mfa_enabled INTEGER NOT NULL DEFAULT 0, mfa_codes TEXT);
CREATE TABLE sessions (
    id TEXT PRIMARY KEY,
    user_id TEXT NOT NULL,
    token_hash TEXT NOT NULL UNIQUE,
    csrf_secret TEXT NOT NULL,
    ip TEXT,
    user_agent TEXT,
    created_at TEXT NOT NULL,
    last_seen_at TEXT NOT NULL,
    expires_at TEXT NOT NULL,
    absolute_expires_at TEXT NOT NULL
  );
CREATE TABLE login_attempts (
    id TEXT PRIMARY KEY,
    email TEXT NOT NULL,
    ip TEXT,
    successful INTEGER NOT NULL DEFAULT 0,
    created_at TEXT NOT NULL
  );
CREATE TABLE number_sequences (
    entity TEXT NOT NULL,
    period TEXT NOT NULL,
    last_number INTEGER NOT NULL DEFAULT 0,
    PRIMARY KEY (entity, period)
  );
CREATE TABLE clients (
    id TEXT PRIMARY KEY,
    number TEXT,
    display_name TEXT NOT NULL,
    first_name TEXT,
    last_name TEXT,
    email TEXT,
    phone TEXT,
    address1 TEXT,
    address2 TEXT,
    city TEXT,
    postal_code TEXT,
    country TEXT NOT NULL DEFAULT 'Polynésie française',
    tax_id TEXT,
    currency TEXT NOT NULL DEFAULT 'XPF',
    payment_terms INTEGER NOT NULL DEFAULT 30,
    is_tax_exempt INTEGER NOT NULL DEFAULT 0,
    notes TEXT,
    archived INTEGER NOT NULL DEFAULT 0,
    created_at TEXT NOT NULL,
    updated_at TEXT NOT NULL,
    deleted_at TEXT
  );
CREATE TABLE client_contacts (
    id TEXT PRIMARY KEY,
    client_id TEXT NOT NULL,
    first_name TEXT,
    last_name TEXT,
    email TEXT,
    phone TEXT,
    is_primary INTEGER NOT NULL DEFAULT 0,
    created_at TEXT NOT NULL,
    FOREIGN KEY (client_id) REFERENCES clients(id) ON DELETE CASCADE
  );
CREATE TABLE products (
    id TEXT PRIMARY KEY,
    product_key TEXT,
    name TEXT NOT NULL,
    description TEXT,
    unit_price INTEGER NOT NULL DEFAULT 0,
    cost INTEGER NOT NULL DEFAULT 0,
    quantity_milli INTEGER NOT NULL DEFAULT 0,
    track_quantity INTEGER NOT NULL DEFAULT 0,
    tax_rate INTEGER NOT NULL DEFAULT 0,
    created_at TEXT NOT NULL,
    updated_at TEXT NOT NULL,
    deleted_at TEXT
  );
CREATE TABLE tax_rates (
    id TEXT PRIMARY KEY,
    name TEXT NOT NULL,
    rate INTEGER NOT NULL,
    is_default INTEGER NOT NULL DEFAULT 0,
    created_at TEXT NOT NULL
  );
CREATE TABLE invoices (
    id TEXT PRIMARY KEY,
    client_id TEXT NOT NULL,
    number TEXT,
    status TEXT NOT NULL DEFAULT 'draft',
    date TEXT NOT NULL,
    due_date TEXT,
    currency TEXT NOT NULL DEFAULT 'XPF',
    subtotal INTEGER NOT NULL DEFAULT 0,
    discount_type TEXT NOT NULL DEFAULT 'percent',
    discount_value INTEGER NOT NULL DEFAULT 0,
    discount_total INTEGER NOT NULL DEFAULT 0,
    tax_total INTEGER NOT NULL DEFAULT 0,
    total INTEGER NOT NULL DEFAULT 0,
    paid_total INTEGER NOT NULL DEFAULT 0,
    balance INTEGER NOT NULL DEFAULT 0,
    tax_exempt INTEGER NOT NULL DEFAULT 0,
    po_number TEXT,
    line_items TEXT NOT NULL DEFAULT '[]',
    notes TEXT,
    terms TEXT,
    footer TEXT,
    recurring_id TEXT,
    sent_at TEXT,
    paid_at TEXT,
    cancelled_at TEXT,
    created_by TEXT,
    created_at TEXT NOT NULL,
    updated_at TEXT NOT NULL,
    deleted_at TEXT
  );
CREATE TABLE payments (
    id TEXT PRIMARY KEY,
    client_id TEXT NOT NULL,
    number TEXT,
    date TEXT NOT NULL,
    amount INTEGER NOT NULL,
    method TEXT NOT NULL DEFAULT 'transfer',
    reference TEXT,
    notes TEXT,
    status TEXT NOT NULL DEFAULT 'completed',
    created_by TEXT,
    created_at TEXT NOT NULL,
    updated_at TEXT NOT NULL,
    deleted_at TEXT
  );
CREATE TABLE payment_allocations (
    id TEXT PRIMARY KEY,
    payment_id TEXT NOT NULL,
    invoice_id TEXT NOT NULL,
    amount INTEGER NOT NULL,
    created_at TEXT NOT NULL,
    FOREIGN KEY (payment_id) REFERENCES payments(id) ON DELETE CASCADE
  );
CREATE TABLE quotes (
    id TEXT PRIMARY KEY,
    client_id TEXT NOT NULL,
    number TEXT,
    status TEXT NOT NULL DEFAULT 'draft',
    date TEXT NOT NULL,
    valid_until TEXT,
    currency TEXT NOT NULL DEFAULT 'XPF',
    subtotal INTEGER NOT NULL DEFAULT 0,
    discount_type TEXT NOT NULL DEFAULT 'percent',
    discount_value INTEGER NOT NULL DEFAULT 0,
    discount_total INTEGER NOT NULL DEFAULT 0,
    tax_total INTEGER NOT NULL DEFAULT 0,
    total INTEGER NOT NULL DEFAULT 0,
    tax_exempt INTEGER NOT NULL DEFAULT 0,
    line_items TEXT NOT NULL DEFAULT '[]',
    notes TEXT,
    terms TEXT,
    converted_invoice_id TEXT,
    sent_at TEXT,
    created_by TEXT,
    created_at TEXT NOT NULL,
    updated_at TEXT NOT NULL,
    deleted_at TEXT
  );
CREATE TABLE credits (
    id TEXT PRIMARY KEY,
    client_id TEXT NOT NULL,
    number TEXT,
    status TEXT NOT NULL DEFAULT 'draft',
    date TEXT NOT NULL,
    currency TEXT NOT NULL DEFAULT 'XPF',
    subtotal INTEGER NOT NULL DEFAULT 0,
    discount_type TEXT NOT NULL DEFAULT 'percent',
    discount_value INTEGER NOT NULL DEFAULT 0,
    discount_total INTEGER NOT NULL DEFAULT 0,
    tax_total INTEGER NOT NULL DEFAULT 0,
    total INTEGER NOT NULL DEFAULT 0,
    applied_total INTEGER NOT NULL DEFAULT 0,
    balance INTEGER NOT NULL DEFAULT 0,
    tax_exempt INTEGER NOT NULL DEFAULT 0,
    line_items TEXT NOT NULL DEFAULT '[]',
    notes TEXT,
    terms TEXT,
    created_by TEXT,
    created_at TEXT NOT NULL,
    updated_at TEXT NOT NULL,
    deleted_at TEXT
  );
CREATE TABLE credit_allocations (
    id TEXT PRIMARY KEY,
    credit_id TEXT NOT NULL,
    invoice_id TEXT NOT NULL,
    amount INTEGER NOT NULL,
    created_at TEXT NOT NULL
  );
CREATE TABLE recurring_invoices (
    id TEXT PRIMARY KEY,
    client_id TEXT NOT NULL,
    number TEXT,
    status TEXT NOT NULL DEFAULT 'draft',
    frequency TEXT NOT NULL DEFAULT 'monthly',
    interval_count INTEGER NOT NULL DEFAULT 1,
    next_run_date TEXT NOT NULL,
    end_date TEXT,
    remaining_cycles INTEGER,
    auto_send INTEGER NOT NULL DEFAULT 0,
    currency TEXT NOT NULL DEFAULT 'XPF',
    discount_type TEXT NOT NULL DEFAULT 'percent',
    discount_value INTEGER NOT NULL DEFAULT 0,
    tax_exempt INTEGER NOT NULL DEFAULT 0,
    line_items TEXT NOT NULL DEFAULT '[]',
    notes TEXT,
    terms TEXT,
    last_generated_at TEXT,
    created_by TEXT,
    created_at TEXT NOT NULL,
    updated_at TEXT NOT NULL,
    deleted_at TEXT
  );
CREATE TABLE expenses (
    id TEXT PRIMARY KEY,
    vendor_id TEXT,
    client_id TEXT,
    category TEXT NOT NULL DEFAULT 'other',
    date TEXT NOT NULL,
    amount INTEGER NOT NULL,
    tax_amount INTEGER NOT NULL DEFAULT 0,
    payment_method TEXT NOT NULL DEFAULT 'transfer',
    reference TEXT,
    notes TEXT,
    is_billable INTEGER NOT NULL DEFAULT 0,
    invoice_id TEXT,
    created_by TEXT,
    created_at TEXT NOT NULL,
    updated_at TEXT NOT NULL,
    deleted_at TEXT
  );
CREATE TABLE vendors (
    id TEXT PRIMARY KEY,
    number TEXT,
    name TEXT NOT NULL,
    email TEXT,
    phone TEXT,
    address1 TEXT,
    city TEXT,
    postal_code TEXT,
    country TEXT NOT NULL DEFAULT 'Polynésie française',
    tax_id TEXT,
    notes TEXT,
    created_at TEXT NOT NULL,
    updated_at TEXT NOT NULL,
    deleted_at TEXT
  );
CREATE TABLE purchase_orders (
    id TEXT PRIMARY KEY,
    vendor_id TEXT NOT NULL,
    number TEXT,
    status TEXT NOT NULL DEFAULT 'draft',
    date TEXT NOT NULL,
    expected_date TEXT,
    currency TEXT NOT NULL DEFAULT 'XPF',
    subtotal INTEGER NOT NULL DEFAULT 0,
    discount_type TEXT NOT NULL DEFAULT 'percent',
    discount_value INTEGER NOT NULL DEFAULT 0,
    discount_total INTEGER NOT NULL DEFAULT 0,
    tax_total INTEGER NOT NULL DEFAULT 0,
    total INTEGER NOT NULL DEFAULT 0,
    line_items TEXT NOT NULL DEFAULT '[]',
    notes TEXT,
    created_by TEXT,
    created_at TEXT NOT NULL,
    updated_at TEXT NOT NULL,
    deleted_at TEXT
  );
CREATE TABLE projects (
    id TEXT PRIMARY KEY,
    client_id TEXT,
    name TEXT NOT NULL,
    description TEXT,
    status TEXT NOT NULL DEFAULT 'active',
    budget INTEGER NOT NULL DEFAULT 0,
    start_date TEXT,
    deadline TEXT,
    created_by TEXT,
    created_at TEXT NOT NULL,
    updated_at TEXT NOT NULL,
    deleted_at TEXT
  );
CREATE TABLE tasks (
    id TEXT PRIMARY KEY,
    project_id TEXT,
    client_id TEXT,
    title TEXT NOT NULL,
    description TEXT,
    status TEXT NOT NULL DEFAULT 'todo',
    minutes INTEGER NOT NULL DEFAULT 0,
    hourly_rate INTEGER NOT NULL DEFAULT 0,
    billable INTEGER NOT NULL DEFAULT 1,
    invoice_id TEXT,
    created_by TEXT,
    created_at TEXT NOT NULL,
    updated_at TEXT NOT NULL,
    deleted_at TEXT
  );
CREATE TABLE bank_accounts (
    id TEXT PRIMARY KEY,
    name TEXT NOT NULL,
    bank_name TEXT,
    iban TEXT,
    currency TEXT NOT NULL DEFAULT 'XPF',
    opening_balance INTEGER NOT NULL DEFAULT 0,
    created_at TEXT NOT NULL,
    updated_at TEXT NOT NULL
  );
CREATE TABLE bank_transactions (
    id TEXT PRIMARY KEY,
    account_id TEXT NOT NULL,
    date TEXT NOT NULL,
    label TEXT NOT NULL,
    amount INTEGER NOT NULL,
    reference TEXT,
    status TEXT NOT NULL DEFAULT 'unmatched',
    matched_payment_id TEXT,
    created_at TEXT NOT NULL
  );
CREATE TABLE activities (
    id TEXT PRIMARY KEY,
    user_id TEXT,
    action TEXT NOT NULL,
    entity_type TEXT NOT NULL,
    entity_id TEXT,
    summary TEXT NOT NULL,
    meta TEXT,
    created_at TEXT NOT NULL
  , before_json TEXT, after_json TEXT, ip TEXT, prev_hash TEXT, hash TEXT);
CREATE TABLE mfa_challenges (
    id TEXT PRIMARY KEY,
    user_id TEXT NOT NULL,
    token_hash TEXT NOT NULL UNIQUE,
    expires_at TEXT NOT NULL,
    used_at TEXT,
    created_at TEXT NOT NULL
  );
CREATE TABLE period_locks (
    period TEXT PRIMARY KEY,
    note TEXT,
    closed_at TEXT NOT NULL,
    closed_by TEXT,
    FOREIGN KEY (closed_by) REFERENCES users(id)
  );
CREATE TABLE invoice_tax_lines (
    id TEXT PRIMARY KEY,
    invoice_id TEXT NOT NULL,
    rate INTEGER NOT NULL,
    base INTEGER NOT NULL,
    amount INTEGER NOT NULL,
    created_at TEXT NOT NULL,
    UNIQUE (invoice_id, rate)
  );
CREATE INDEX idx_sessions_user ON sessions(user_id);
CREATE INDEX idx_login_attempts_email ON login_attempts(email, created_at);
CREATE INDEX idx_clients_name ON clients(display_name);
CREATE UNIQUE INDEX idx_invoices_number ON invoices(number);
CREATE INDEX idx_invoices_client ON invoices(client_id);
CREATE INDEX idx_invoices_status ON invoices(status, date);
CREATE INDEX idx_payments_client ON payments(client_id);
CREATE INDEX idx_allocations_payment ON payment_allocations(payment_id);
CREATE INDEX idx_allocations_invoice ON payment_allocations(invoice_id);
CREATE UNIQUE INDEX idx_quotes_number ON quotes(number);
CREATE INDEX idx_quotes_client ON quotes(client_id);
CREATE UNIQUE INDEX idx_credits_number ON credits(number);
CREATE INDEX idx_expenses_date ON expenses(date);
CREATE INDEX idx_bank_tx_date ON bank_transactions(date);
CREATE INDEX idx_activities_created ON activities(created_at);
CREATE INDEX idx_mfa_challenges_user ON mfa_challenges(user_id);
CREATE INDEX idx_invoice_tax_lines_invoice ON invoice_tax_lines(invoice_id);
CREATE INDEX idx_invoices_client_status ON invoices(client_id, status);
CREATE INDEX idx_invoices_date ON invoices(date);
CREATE INDEX idx_invoices_due ON invoices(status, due_date);
CREATE INDEX idx_quotes_status ON quotes(status, date);
CREATE INDEX idx_credits_client ON credits(client_id);
CREATE INDEX idx_credit_allocations_invoice ON credit_allocations(invoice_id);
CREATE INDEX idx_payments_status_date ON payments(status, date);
CREATE INDEX idx_expenses_status_date ON expenses(category, date);
CREATE INDEX idx_expenses_vendor ON expenses(vendor_id);
CREATE INDEX idx_purchase_orders_vendor ON purchase_orders(vendor_id);
CREATE INDEX idx_tasks_project ON tasks(project_id);
CREATE INDEX idx_activities_user ON activities(user_id);
CREATE INDEX idx_recurring_next_run ON recurring_invoices(status, next_run_date);